import React from 'react';
import './MenuForms.css';

const MenuForms = () => {
    const scrollToInfo = () => {
        const infoSection = document.getElementById('info-section');
        if (infoSection) {
            infoSection.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return (
        <div className="menu-form">
            <h2>¿En qué puede ayudarte FinanTec?</h2>
            <div className="menu-options">
                <div className="saving-box green" onClick={scrollToInfo}>
                    <div className="icon">💰</div>
                    <span>Generar Ahorro</span>
                </div>
                <div className="saving-box blue" onClick={scrollToInfo}>
                    <div className="icon">🏦</div>
                    <span>Plan de Jubilación</span>
                </div>
                <div className="saving-box pink" onClick={scrollToInfo}>
                    <div className="icon">🎯</div>
                    <span>Metas Largo/Corto Plazo</span>
                </div>
            </div>

            {/* Sección de información */}
            <div id="info-section" className="info-section">
                <h3>Información sobre Generar Ahorro</h3>
                <p>FinanTec es tu aliado en el camino hacia una mejor salud financiera. Aquí te proporcionamos herramientas y recursos para ayudarte a:</p>
                <p>- Establecer metas de ahorro realistas.</p>
                <p>- Crear un presupuesto efectivo que se ajuste a tus necesidades.</p>
                <p>- Identificar y reducir gastos innecesarios para maximizar tu capacidad de ahorro.</p>
                <p>- Planificar tu futuro y asegurar un retiro confortable.</p>
                <p>¡Comienza hoy y transforma tu manera de gestionar tus finanzas!</p>
            </div>
        </div>
    );
};

export default MenuForms;
